const trig = $('When Executed by Another Workflow').first().json;
const settings = $('Load clinic_settings').first().json;
const doctors = $('Load doctors').all().map(i => i.json).filter(d => d.name);
const avail = $('Load week availability').all().map(i => i.json).filter(a => a.doctor_name);
let faqs = [];
try {
  faqs = $('Load preguntas frecuentes').all().map(i => i.json)
    .filter(r => r && r.pregunta && r.respuesta);
} catch (e) { faqs = []; }
const dayNames = ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];

function fmtTime(t) {
  if (!t) return '';
  const s = String(t);
  return s.length >= 5 ? s.slice(0, 5) : s;
}

const byDoc = {};
for (const a of avail) {
  if (!byDoc[a.doctor_name]) byDoc[a.doctor_name] = [];
  const day = Number(a.day);
  byDoc[a.doctor_name].push(`${dayNames[day] || day} ${fmtTime(a.start_time)}-${fmtTime(a.end_time)}`);
}

let obras = settings.obras_sociales;
if (typeof obras === 'string') {
  try { obras = JSON.parse(obras); } catch (e) { obras = [obras]; }
}
if (!Array.isArray(obras)) obras = [];

const dispOn = [1, '1', true, 'true'].includes(settings.disponibilidad_enabled)
  || Number(settings.disponibilidad_enabled) === 1;

const medicosLines = doctors.map(d => {
  const hours = byDoc[d.name];
  if (hours && hours.length) return ` - ${d.name}: ${hours.join(', ')}.`;
  return ` - ${d.name}: (sin horarios cargados esta semana).`;
}).join('\n');

const medicosBlock = dispOn
  ? `Médicos y horarios (semana actual):\n${medicosLines || ' - (sin médicos activos)'}`
  : `Médicos activos (SIN horarios individuales — no inventes ni digas a qué hora atiende cada uno):\n${doctors.map(d => ' - ' + d.name + '.').join('\n') || ' - (sin médicos activos)'}\nSi preguntan horarios de un doctor, respondé EXACTAMENTE: Le comunicaremos con una secretaria para darle a saber los horarios de los doctores`;


const faqBlock = faqs.length
  ? (`Preguntas frecuentes (si el mensaje del paciente coincide con UNA de estas preguntas — mismo tema, paráfrasis cercana — respondé SOLO con la respuesta asociada, texto exacto, sin agregar nada:\\n`
    + faqs.map((f, i) => `### FAQ ${i + 1}\\nPregunta: ${f.pregunta}\\nRespuesta exacta: ${f.respuesta}`).join('\\n\\n')
    + (dispOn ? '' : '\\n\\nIMPORTANTE: si la FAQ es sobre horarios de un médico/doctor y arriba dice que no hay horarios individuales, IGNORÁ esa FAQ y respondé exactamente: Le comunicaremos con una secretaria para darle a saber los horarios de los doctores'))
  : '';

const system = `Sos la asistente del Centro Oftalmologico Artigas. Respondé SOLO usando la siguiente información. Si la pregunta no se puede responder con esto, decí que no contas con esa informacion pero lo vas a averiguar para hacerle saber.

Ubicación (donde queda):
 - ${settings.address || 'Avenida Nicolas Avellaneda 347'}.
Horarios (a que hora abre y cierra la clinica):
 - ${settings.clinic_hours || ''}.

${medicosBlock}

${faqBlock}

Obras sociales aceptadas:
${obras.map(o => ` - ${o}.`).join('\n')}

## Reglas de ORO:
 - No vas a contestar nada que no este relacionado los medicos, los horarios de los medicos (solo si están disponibles arriba), Ubicacion, Horario de la clinica u obras sociales aceptadas.
 - Si arriba dice que NO hay horarios individuales, NUNCA inventes días ni horas de un médico.
 - Si hay Preguntas frecuentes y el mensaje coincide con una, respondé SOLO esa Respuesta exacta.
 - Vas a mantener un tono agradable y amistoso, sin perder el profesionalismo.
 - Solo vas a poner "hola!" en el primer mensaje que te llegue en el día.`;

return [{
  json: {
    telefono: trig.telefono,
    texto: trig.texto,
    conversation_id: trig.conversation_id,
    account_id: trig.account_id,
    system_prompt: system
  }
}];

const trig = $('Build system prompt').first().json;
const text = $input.first().json.text || $input.first().json.response || String($input.first().json);
return [{
  json: {
    conversation_id: trig.conversation_id,
    account_id: trig.account_id,
    cw_body: {
      content: text,
      message_type: 'outgoing',
      private: false
    }
  }
}];
